{
  "events": [
    {
      "key": "school_circle",
      "choices": [
        {
          "index": 2,
          "label": "시로와 학생들을 먼저 대피시킨다",
          "result": "시로의 안내에 따라 학생들을 안전한 곳으로 신속하게 이동시킨다. 구조물의 약점을 파악하며 대피 경로를 확보한다. 행동력이 소모되고 학생들의 안전을 확보했다."
        },
        {
          "index": 3,
          "label": "140골드로 기록용품을 마련하고 린과 대피 순서를 나눈다",
          "result": "린과 협력하여 체계적인 대피 우선순위를 설정한다. 준비된 기록용품으로 상황을 정리하며 이동을 준비한다. 140골드를 지불하고 정교한 계획을 수립했다."
        }
      ]
    },
    {
      "key": "school_circle_trace",
      "choices": [
        {
          "index": 3,
          "label": "180골드로 기록을 나눠 적고 린과 다시 확인할 차례를 맞춘다",
          "result": "린과 역할을 분담하여 남은 흔적들을 꼼꼼하게 기록한다. 다음 조사 단계를 위한 시간과 순서를 조율한다. 180골드를 지불하고 조사 효율을 높였다."
        }
      ]
    },
    {
      "key": "temple_gate",
      "choices": [
        {
          "index": 3,
          "label": "160골드로 돌아갈 표식을 마련하고 세이버와 발을 둘 길을 나눈다",
          "result": "세이버와 보폭을 맞추며 어새신의 공격을 회피할 경로를 확보한다. 퇴각을 위한 표식을 설치하며 전술적 위치를 점한다. 160골드를 지불하고 이동의 안정성을 확보했다."
        }
      ]
    },
    {
      "key": "fy_club_inventory",
      "choices": [
        {
          "index": 2,
          "label": "시로와 넓은 길목의 확인까지 맡는다",
          "result": "시로와 함께 부실 주변의 넓은 구역을 수색한다. 누락된 상자의 행방을 찾기 위해 구조적 확인을 병행한다. 추가 비용 없이 조사 범위를 확장했다."
        },
        {
          "index": 3,
          "label": "160골드로 포장을 마련하고 시로와 아직 이름 없는 상자의 몫을 맡는다",
          "result": "시로와 협력하여 주인 없는 상자의 목록을 정리한다. 포장재를 준비하며 책임 소재를 명확히 할 준비를 한다. 160골드를 지불하고 업무 분담을 완료했다."
        }
      ]
    }
  ]
}
